const POOL_REFERENCE = 'pool/';

/**
 * One pocket of a business' estate. The finance system rewrites the whole set
 * whenever a team moves, so the pools are kept together in a single document
 * rather than one object each.
 */
export class AttributionPool {
    /** The code spend sitting on this pool is booked to. */
    public chargeCode: string;
}

export class AttributionPoolDocument {
    public revision: string;
    public pools: Record<string, AttributionPool>;
}

/**
 * The attribution material a business keeps beside its onboarding record.
 */
export class AttributionDirectory {
    private readonly pools: Record<string, AttributionPool>;

    private constructor(pools: Record<string, AttributionPool>) {
        this.pools = pools;
    }

    static async load(bucket: string, prefix: string): Promise<AttributionDirectory> {
        const document = await getDocument<AttributionPoolDocument>(bucket, `${prefix}pools.json`);
        return new AttributionDirectory(document?.pools ?? {});
    }

    /**
     * The charge code named by the attribution reference a usage line carries.
     */
    chargeCodeFor(reference: string): string {
        if (!reference || !reference.startsWith(POOL_REFERENCE)) {
            return undefined;
        }
        return this.pools[reference.slice(POOL_REFERENCE.length)]?.chargeCode;
    }
}
import { getDocument } from '../../utils/aws/s3.js';

/**
 * An AWS account a business has handed us for measurement.
 */
export class MeteredAccount {
    /**
     * The account the metering role lives in.
     * @example "445566778899"
     */
    public accountId: string;
    /**
     * The role we assume to read the account.
     * @example "arn:aws:iam::445566778899:role/paigo-metering"
     */
    public roleArn: string;
    /**
     * The external id the role's trust policy asks for, when it asks for one.
     */
    public externalId?: string;
    /**
     * The region the business named as the account's home when it onboarded.
     * @example "us-east-1"
     */
    public region: string;
    /**
     * The bucket the account's own collectors write their usage exports to.
     * @example "paigo-usage-loomwright-platform"
     */
    public usageBucket: string;
}

/**
 * The onboarding record a business keeps in its metering bucket. It is written
 * by the onboarding flow and read by every collector that has to sweep more
 * than one account.
 */
export class MeteringRegistry {
    public businessID: string;
    /**
     * Key prefix the usage exports sit under inside each account's usage
     * bucket, one folder per account and one object per export.
     * @example "usage/"
     */
    public usageExportPrefix: string;
    /**
     * Key prefix the business' attribution material sits under in the metering
     * bucket itself.
     * @example "attribution/"
     */
    public attributionPrefix: string;
    public accounts: Array<MeteredAccount>;

    static async load(bucket: string, key: string): Promise<MeteringRegistry> {
        return getDocument<MeteringRegistry>(bucket, key);
    }
}
import { getDocument, listDocumentKeys } from '../../utils/aws/s3.js';

/**
 * One metered line as the account's collector wrote it out.
 */
export class UsageExportLine {
    public lineId: string;
    /**
     * The resource the collector measured.
     * @example "i-0a3f19c2d4e5b6708"
     */
    public resourceId: string;
    /**
     * The region the resource was measured in.
     * @example "eu-west-1"
     */
    public region: string;
    /** How much of the dimension the line carries. */
    public quantity: number;
    /** What the line came to in the reporting currency. */
    public amount: number;
    /**
     * Where in the business' attribution material this line starts.
     * @example "pool/aurora-ci"
     */
    public attribution: string;
}

/**
 * One usage export. A collector drops an export into its account's usage
 * bucket every time it finishes a sweep, so an account accumulates one object
 * per sweep and a single export may cover several regions at once.
 */
export class UsageExportBatch {
    public batchId: string;
    public coveringDate: string;
    public lines: Array<UsageExportLine>;
}

export class UsageExport {
    /**
     * Every metered line an account has exported.
     */
    static async linesForAccount(
        bucket: string,
        prefix: string,
        accountId: string,
        credentials = undefined,
    ): Promise<Array<UsageExportLine>> {
        const keys = await listDocumentKeys(bucket, `${prefix}${accountId}/`, credentials);
        const batches = await Promise.all(keys.map((key) => getDocument<UsageExportBatch>(bucket, key, credentials)));
        const lines: Array<UsageExportLine> = [];
        batches.forEach((batch) => {
            (batch?.lines ?? []).forEach((line) => lines.push(line));
        });
        return lines;
    }
}
import { Point } from '@influxdata/influxdb-client';
import { InfluxService } from '../../../influx/influx.service.js';

/**
 * What one charge code ended up carrying once every metered line the business
 * exported had been attributed.
 */
export class AttributedSpendEntity {
    public static _measurement = 'AttributedSpendData';

    public businessID: string;
    /**
     * The code the spend is booked to.
     * @example "cc-platform-core"
     */
    public chargeCode: string;
    /** How much of the metered dimension sits under the code. */
    public quantity: number;
    /** What that came to in the reporting currency. */
    public amount: number;
    /** How many exported lines make up the two figures above. */
    public lineCount: number;

    constructor({ businessID, chargeCode, quantity, amount, lineCount }: AttributedSpendEntity) {
        this.businessID = businessID;
        this.chargeCode = chargeCode;
        this.quantity = quantity;
        this.amount = amount;
        this.lineCount = lineCount;
    }

    public static transformer(entity: AttributedSpendEntity, influxService: InfluxService): Point {
        const { businessID, chargeCode, quantity, amount, lineCount } = entity;

        const point = influxService.getPoint(AttributedSpendEntity._measurement);
        point.tag('businessID', businessID);
        point.tag('chargeCode', chargeCode);
        point.floatField('quantity', quantity);
        point.floatField('amount', amount);
        point.intField('lineCount', lineCount);

        return point;
    }

    public static dbModelToEntity(dbModel: any): AttributedSpendEntity {
        const { businessID, chargeCode, _value, amount, lineCount } = dbModel;

        return new AttributedSpendEntity({
            businessID,
            chargeCode,
            quantity: _value,
            amount,
            lineCount,
        });
    }
}
"
}

