/**
 * The tags one instance carries, keyed by tag name. Returns undefined when the
 * instance is not in the account/region asked for, so callers can treat a
 * dangling reference as a miss instead of a failure.
 */
export const getInstanceTags = async (
    region: string,
    creds,
    instanceId: string,
): Promise<Record<string, string>> => {
    try {
        const ec2Client = new EC2Client({ region, credentials: creds });
        const { Reservations } = await ec2Client.send(
            new DescribeInstancesCommand({ InstanceIds: [instanceId] }),
        );
        const instance = flattenDeep((Reservations ?? []).map(({ Instances }) => Instances ?? [])).find(
            ({ InstanceId }) => InstanceId === instanceId,
        );
        if (!instance) {
            return undefined;
        }
        return (instance.Tags ?? []).reduce((tags, { Key, Value }) => ({ ...tags, [Key]: Value }), {});
    } catch (error) {
        if (error?.name === 'InvalidInstanceID.NotFound') {
            return undefined;
        }
        throw error;
    }
};
