import { Logger } from '@nestjs/common';
import { getDocument } from '../../utils/aws/s3.js';
import { getParameterValue } from '../../utils/aws/awsSSM.js';
import { getInstanceTags } from '../../utils/aws/awsEc2.js';
import { MeteredAccount, credentialsForAccount } from './meteringAccounts.entity.js';

const POOL_REFERENCE = 'pool/';
const UNIT_REFERENCE = 'unit/';
const ALIAS_REFERENCE = 'alias/';
const NODE_REFERENCE = 'node/';

/** Where a business' alias records live outside of its metering bucket. */
const ALIAS_PARAMETER_PREFIX = '/paigo/attribution/alias/';
/** The tags an instance carries when it takes part in attribution. */
const NODE_CHARGE_CODE_TAG = 'paigoChargeCode';
const NODE_ROLLS_INTO_TAG = 'paigoRollsInto';

/** Guards against attribution material that points onwards without ever ending. */
const MAX_CHAIN_LENGTH = 64;

/**
 * One step of an attribution chain: the code the step itself names, and the
 * reference it hands the spend on to, when it hands it on at all.
 */
class AttributionLink {
    public chargeCode?: string;
    public passesTo?: string;
}

/**
 * One pocket of a business' estate. The finance system rewrites the whole set
 * whenever a team moves, so the pools are kept together in a single document
 * rather than one object each.
 */
export class AttributionPool {
    /** The code spend sitting on this pool is booked to. */
    public chargeCode: string;
    /**
     * Where the pool passes its spend on to, when it does not keep it. The
     * owner named here carries the spend instead of the pool itself.
     * @example "unit/fernlea"
     */
    public rollsUpTo?: string;
}

export class AttributionPoolDocument {
    public revision: string;
    public pools: Record<string, AttributionPool>;
}

/**
 * One business unit the finance system keeps as its own object beside the pool
 * document.
 */
export class AttributionUnit {
    public unitId: string;
    /** The code spend sitting on this unit is booked to. */
    public chargeCode: string;
    /**
     * The owner this unit passes its spend on to, when it passes it on.
     * @example "alias/zircon"
     */
    public parentRef?: string;
}

/**
 * The attribution material a business keeps beside its onboarding record.
 *
 * A usage line names where its spend starts, but a pool, unit, alias or
 * instance may pass that spend on to another owner, and that owner may pass it
 * on again. The directory walks the whole chain so spend lands on the code that
 * ultimately carries it rather than on the first code it meets.
 */
export class AttributionDirectory {
    private static readonly logger = new Logger(AttributionDirectory.name);

    private readonly pools: Record<string, AttributionPool>;

    /** The metering bucket and prefix the rest of the material sits under. */
    private readonly bucket: string;

    private readonly prefix: string;

    /** The accounts we may read instances from, keyed by account id. */
    private readonly accounts: Record<string, MeteredAccount>;

    private readonly unitCache = new Map<string, Promise<AttributionUnit>>();

    private readonly aliasCache = new Map<string, Promise<string>>();

    private readonly nodeCache = new Map<string, Promise<Record<string, string>>>();

    private readonly resolutionCache = new Map<string, string>();

    private constructor(
        pools: Record<string, AttributionPool>,
        bucket: string,
        prefix: string,
        accounts: Array<MeteredAccount>,
    ) {
        this.pools = pools;
        this.bucket = bucket;
        this.prefix = prefix;
        this.accounts = (accounts ?? []).reduce((known, account) => ({ ...known, [account.accountId]: account }), {});
    }

    static async load(bucket: string, prefix: string, accounts: Array<MeteredAccount> = []): Promise<AttributionDirectory> {
        const document = await getDocument<AttributionPoolDocument>(bucket, `${prefix}pools.json`);
        return new AttributionDirectory(document?.pools ?? {}, bucket, prefix, accounts);
    }

    /**
     * The code that ends up carrying a usage line's spend. The reference the
     * line carries is followed through every owner that passes the cost on, so
     * the answer is the last owner in the chain rather than the first one.
     *
     * When the chain turns back on itself the owners in the loop share a code
     * between them, and that shared code is the one used.
     */
    async chargeCodeFor(reference: string): Promise<string> {
        if (!reference) {
            return undefined;
        }
        if (this.resolutionCache.has(reference)) {
            return this.resolutionCache.get(reference);
        }

        const visited = new Map<string, number>();
        const codes: Array<string> = [];
        let current = reference;
        let carried: string;

        while (current) {
            if (visited.has(current)) {
                const shared = AttributionDirectory.sharedCycleCode(codes.slice(visited.get(current)));
                AttributionDirectory.logger.warn(
                    `Attribution chain from ${reference} repeats at ${current}, booking to ${shared ?? carried}`,
                );
                carried = shared ?? carried;
                break;
            }
            visited.set(current, codes.length);

            // Each step has to be read before we know where the chain goes next.
            // eslint-disable-next-line no-await-in-loop
            const link = await this.linkFor(current);
            if (!link) {
                AttributionDirectory.logger.warn(
                    `Attribution reference ${current} reached from ${reference} is not in the business' material`,
                );
                break;
            }
            codes.push(link.chargeCode);
            if (link.chargeCode) {
                carried = link.chargeCode;
            }
            if (codes.length >= MAX_CHAIN_LENGTH) {
                AttributionDirectory.logger.warn(
                    `Attribution chain from ${reference} is longer than ${MAX_CHAIN_LENGTH} owners, booking to ${carried}`,
                );
                break;
            }
            current = link.passesTo;
        }

        this.resolutionCache.set(reference, carried);
        return carried;
    }

    /**
     * The code the owners caught in a repeating chain hold between them. They
     * normally all name the same code, and that is the code the cycle carries;
     * when they disagree the one the most of them name is used.
     */
    private static sharedCycleCode(codes: Array<string>): string {
        const named = codes.filter((code) => code);
        if (named.length === 0) {
            return undefined;
        }
        const tally = named.reduce((counts, code) => ({ ...counts, [code]: (counts[code] ?? 0) + 1 }), {});
        return Object.keys(tally)
            .sort((left, right) => tally[right] - tally[left] || left.localeCompare(right))
            .shift();
    }

    /**
     * What one attribution reference names, whichever kind of owner it points at.
     */
    private async linkFor(reference: string): Promise<AttributionLink> {
        if (reference.startsWith(POOL_REFERENCE)) {
            const pool = this.pools[reference.slice(POOL_REFERENCE.length)];
            return pool ? { chargeCode: pool.chargeCode, passesTo: pool.rollsUpTo } : undefined;
        }
        if (reference.startsWith(UNIT_REFERENCE)) {
            const unit = await this.unit(reference.slice(UNIT_REFERENCE.length));
            return unit ? { chargeCode: unit.chargeCode, passesTo: unit.parentRef } : undefined;
        }
        if (reference.startsWith(ALIAS_REFERENCE)) {
            const target = await this.alias(reference.slice(ALIAS_REFERENCE.length));
            // An alias only ever stands in for another owner, it books nothing itself.
            return target ? { passesTo: target } : undefined;
        }
        if (reference.startsWith(NODE_REFERENCE)) {
            return this.node(reference.slice(NODE_REFERENCE.length));
        }
        return undefined;
    }

    /**
     * A business unit, read from its own object in the metering bucket.
     */
    private async unit(name: string): Promise<AttributionUnit> {
        if (!this.unitCache.has(name)) {
            this.unitCache.set(
                name,
                getDocument<AttributionUnit>(this.bucket, `${this.prefix}units/${name}.json`).catch(() => undefined),
            );
        }
        return this.unitCache.get(name);
    }

    /**
     * The owner an alias stands in for.
     */
    private async alias(name: string): Promise<string> {
        if (!this.aliasCache.has(name)) {
            this.aliasCache.set(
                name,
                getParameterValue(`${ALIAS_PARAMETER_PREFIX}${name}`).catch(() => undefined),
            );
        }
        return this.aliasCache.get(name);
    }

    /**
     * What an instance named by a `node/<account>/<region>/<instance>` reference
     * carries. The instance lives in one of the business' own accounts, so it is
     * read with that account's credentials rather than our own.
     */
    private async node(target: string): Promise<AttributionLink> {
        const [accountId, region, instanceId] = target.split('/');
        if (!accountId || !region || !instanceId) {
            return undefined;
        }
        const account = this.accounts[accountId];
        if (!account) {
            AttributionDirectory.logger.warn(
                `Attribution reference names instance ${instanceId} in account ${accountId}, which is not onboarded`,
            );
            return undefined;
        }
        const key = `${accountId}/${region}/${instanceId}`;
        if (!this.nodeCache.has(key)) {
            this.nodeCache.set(
                key,
                getInstanceTags(region, credentialsForAccount(account), instanceId).catch(() => undefined),
            );
        }
        const tags = await this.nodeCache.get(key);
        if (!tags) {
            return undefined;
        }
        return { chargeCode: tags[NODE_CHARGE_CODE_TAG], passesTo: tags[NODE_ROLLS_INTO_TAG] };
    }
}
